import{_ as d,o as t,c as a,a0 as o}from"./chunks/framework.K3sFe4KB.js";const f=JSON.parse('{"title":"CLI","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),c={name:"reference/cli.md"};function i(r,e,n,l,s,h){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to &quot;CLI&quot;">​</a></h1><p><code>cicada</code> — calendars as code. Declare calendars in YAML; plan, apply, and detect drift against live providers.</p><p><strong>Global behaviour.</strong> Verbs that read desired state take optional file arguments; with none, the <code>cicada.yaml</code> (or <code>cicada.yml</code>) manifest in the current directory is discovered and its <code>calendars:</code> list used. A <code>kind: Manifest</code> path passed explicitly expands the same way. All verbs exit <code>0</code> on success and <code>1</code> on failure.</p><p><strong>Shared flags.</strong> Provider-facing verbs accept:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--provider &lt;fake|google&gt;</code></td><td><code>fake</code></td><td>Provider adapter</td></tr><tr><td><code>--fake-file &lt;path&gt;</code></td><td><code>.cicada/fake-provider.json</code> beside the manifest</td><td>Fake backend file (test/demo)</td></tr><tr><td><code>--state &lt;path&gt;</code></td><td><code>.cicada/state.yaml</code>; <code>$CICADA_STATE</code> overrides</td><td>Recorded-state file</td></tr></tbody></table><h2 id="cicada-init-dir" tabindex="-1"><code>cicada init [dir]</code> <a class="header-anchor" href="#cicada-init-dir" aria-label="Permalink to &quot;`cicada init [dir]`&quot;">​</a></h2><p>Scaffold <code>cicada.yaml</code>, <code>calendars/work.yaml</code>, and <code>.cicada/</code> in <code>dir</code> (default: current directory). Refuses to overwrite existing files.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--force</code></td><td>Overwrite existing scaffolded files</td></tr></tbody></table><h2 id="cicada-validate-files" tabindex="-1"><code>cicada validate [files…]</code> <a class="header-anchor" href="#cicada-validate-files" aria-label="Permalink to &quot;`cicada validate [files…]`&quot;">​</a></h2><p>Schema shape plus domain invariants per file; manifests expand. Reports <code>✓</code>/<code>✗</code> per file with diagnostics, then <code>N valid, M failed</code>. Exit <code>1</code> when any file errors.</p><h2 id="cicada-plan-files" tabindex="-1"><code>cicada plan [files…]</code> <a class="header-anchor" href="#cicada-plan-files" aria-label="Permalink to &quot;`cicada plan [files…]`&quot;">​</a></h2><p>Diff desired vs recorded vs live into an ordered plan: <code>create</code>, <code>update</code>, <code>delete</code>, <code>replace</code>, <code>noop</code> lines with field-level diffs, drift entries, and capability findings. Exit <code>1</code> on errors or when any plan carries error-severity findings.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--out &lt;path&gt;</code></td><td>Write the <code>cicada/plan-v1</code> JSON document (array when several calendars planned)</td></tr></tbody></table><h2 id="cicada-apply-files" tabindex="-1"><code>cicada apply [files…]</code> <a class="header-anchor" href="#cicada-apply-files" aria-label="Permalink to &quot;`cicada apply [files…]`&quot;">​</a></h2><p>Plan then execute under the state-file advisory lock. Prints the plan, prompts <code>[y/N]</code> unless <code>--auto-approve</code>, then applies ops in order, journalling each into recorded state. Exit <code>1</code> when any op fails — partial applies are honest.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--auto-approve</code></td><td>Skip the confirmation prompt</td></tr><tr><td><code>--resume</code></td><td>Skip ops already journaled as applied (crash recovery)</td></tr><tr><td><code>--force</code></td><td>Overwrite out-of-band edits instead of failing on drift conflict</td></tr><tr><td><code>--notify &lt;none|externalOnly|all&gt;</code></td><td>Attendee-notification override for this run</td></tr></tbody></table><h2 id="cicada-refresh" tabindex="-1"><code>cicada refresh</code> <a class="header-anchor" href="#cicada-refresh" aria-label="Permalink to &quot;`cicada refresh`&quot;">​</a></h2><p>Fold live provider state into recorded state under the lock: update changed records, drop records whose live event is gone, report cicada-tagged live events as adoption candidates. Writes only local state — never the provider.</p><h2 id="cicada-drift" tabindex="-1"><code>cicada drift</code> <a class="header-anchor" href="#cicada-drift" aria-label="Permalink to &quot;`cicada drift`&quot;">​</a></h2><p>Recorded-vs-live comparison. Read-only. Prints <code>missing</code>/<code>modified</code> entries per calendar; exit <code>1</code> when any drift exists (the CI signal).</p><h2 id="cicada-range-files" tabindex="-1"><code>cicada range [files…]</code> <a class="header-anchor" href="#cicada-range-files" aria-label="Permalink to &quot;`cicada range [files…]`&quot;">​</a></h2><p>Expand declared events into occurrences over a window. Default window: <code>today</code> → <code>+7d</code>. With <code>--provider</code>, lists the live remote calendar instead (unmanaged events included).</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--from &lt;bound&gt;</code></td><td>Window start</td></tr><tr><td><code>--to &lt;bound&gt;</code></td><td>Window end (exclusive)</td></tr></tbody></table><p>Bounds: <code>today</code>, <code>+Nd</code>, <code>+Nw</code>, <code>YYYY-MM-DD</code>, a civil datetime, or an RFC 3339 instant — resolved in the calendar&#39;s <code>timeZone</code>.</p><h2 id="cicada-show-id-files" tabindex="-1"><code>cicada show &lt;id&gt; [files…]</code> <a class="header-anchor" href="#cicada-show-id-files" aria-label="Permalink to &quot;`cicada show &lt;id&gt; [files…]`&quot;">​</a></h2><p>One event by stable local id: fields plus occurrences (default window <code>today</code> → <code>+30d</code>, capped at 20 lines). With <code>--provider</code>, resolves the live event by its <code>cicada:id</code> tag and expands its remote rule.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--from</code>, <code>--to</code></td><td>Occurrence window (same grammar as <code>range</code>)</td></tr></tbody></table><h2 id="cicada-fmt-files" tabindex="-1"><code>cicada fmt [files…]</code> <a class="header-anchor" href="#cicada-fmt-files" aria-label="Permalink to &quot;`cicada fmt [files…]`&quot;">​</a></h2><p>Canonical re-serialisation in place: stable field order, normalised scalars, defaults elided. Comments are not preserved.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--check</code></td><td>Write nothing; exit <code>1</code> when any file isn&#39;t canonical (CI)</td></tr><tr><td><code>--sort</code></td><td>Sort events by stable id instead of preserving file order</td></tr></tbody></table><h2 id="cicada-provider-add-google" tabindex="-1"><code>cicada provider add google</code> <a class="header-anchor" href="#cicada-provider-add-google" aria-label="Permalink to &quot;`cicada provider add google`&quot;">​</a></h2><p>Register Google credentials.</p><table tabindex="0"><thead><tr><th>Flag</th><th>Meaning</th></tr></thead><tbody><tr><td><code>--service-account &lt;key.json&gt;</code></td><td>Non-interactive: validate + store a service-account key</td></tr><tr><td><code>--client-id</code>, <code>--client-secret</code></td><td>OAuth client credentials (else <code>CICADA_GOOGLE_CLIENT_ID</code>/<code>_SECRET</code>)</td></tr><tr><td><code>--code</code></td><td>Authorization code — skips the interactive prompt</td></tr></tbody></table><p>OAuth flow: prints a consent URL; a loopback listener on <code>127.0.0.1</code> captures the code when it can bind, otherwise the code or redirect URL is pasted. The refresh token lands at <code>~/.local/state/cicada/secrets/</code> mode <code>0600</code>.</p><h2 id="cicada-mcp" tabindex="-1"><code>cicada mcp</code> <a class="header-anchor" href="#cicada-mcp" aria-label="Permalink to &quot;`cicada mcp`&quot;">​</a></h2><p>Serve MCP over stdio — same options as the <code>cicada-mcp</code> binary: <code>--root</code>, <code>--provider</code>, <code>--fake-file</code>, <code>--state</code>. See <a href="./mcp-tools.html">MCP tools</a>.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Used by</th></tr></thead><tbody><tr><td><code>CICADA_STATE</code></td><td>State file path (all provider-facing verbs)</td></tr><tr><td><code>CICADA_ROOT</code></td><td>MCP server working root</td></tr><tr><td><code>CICADA_GOOGLE_*</code>, <code>GOOGLE_APPLICATION_CREDENTIALS</code></td><td>Google auth — see <a href="./providers.html">providers</a></td></tr><tr><td><code>CICADA_SECRETS_DIR</code></td><td>Secrets directory override</td></tr></tbody></table>',38)])])}const b=d(c,[["render",i]]);export{f as __pageData,b as default};
